    /** Daily points with both averages and how many days they rest on; photos only go to the coach with approval each time. */
    void body(){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Body");fillBody(s);s.show();}
    private void fillBody(WorkoutViews.Sheet s){s.body.removeAllViews();JSONObject bw=overview().optJSONObject("bodyweight");JSONArray daily=bw==null?null:bw.optJSONArray("daily");LinearLayout c=WorkoutViews.card(ui);c.addView(ui.type("Weight",15,20,700,0,ui.text));
        ArrayList<double[]> dots=new ArrayList<>(),seven=new ArrayList<>(),fourteen=new ArrayList<>();int start=0;for(int i=start;daily!=null&&i<daily.length();i++){JSONObject p=daily.optJSONObject(i);double x=LocalDate.parse(p.optString("date")).toEpochDay();dots.add(new double[]{x,p.optDouble("kg")});if(!p.isNull("average_7d"))seven.add(new double[]{x,p.optDouble("average_7d")});if(!p.isNull("average_14d"))fourteen.add(new double[]{x,p.optDouble("average_14d")});}
        if(dots.isEmpty())c.addView(ui.type("No weight logged yet. Weigh in the morning, before food, on the same scale.",13,18,400,0,ui.muted));else{WorkoutViews.Chart chart=new WorkoutViews.Chart(ui);chart.gap=21;chart.line(dots.toArray(new double[0][]),ui.strokeStrong,0).line(fourteen.toArray(new double[0][]),ui.accent,2).line(seven.toArray(new double[0][]),ui.warning,2);c.addView(chart,MainParts.params(ui,-1,ui.dp(120),0,6,0,6));JSONObject latest=bw.optJSONObject("latest");if(latest!=null){c.addView(WorkoutViews.pair(ui,"7-day average",latest.isNull("average_7d")?"Needs 3 days":WorkoutUnits.load(a,latest.optDouble("average_7d"))+" · "+latest.optInt("count_7d")+" days",ui.warning));c.addView(WorkoutViews.pair(ui,"14-day average",latest.isNull("average_14d")?"Needs 5 days":WorkoutUnits.load(a,latest.optDouble("average_14d"))+" · "+latest.optInt("count_14d")+" days",ui.accent));}}s.body.addView(c,WorkoutViews.gap(ui,8));
        Button w=ui.quietButton("Log weight",()->measure(s,"bodyweight","kg","Weight in "+WorkoutUnits.loadLabel(a)));w.setTag("workout_log_weight");s.body.addView(w,WorkoutViews.gap(ui,8));s.body.addView(ui.quietButton("Log soreness",this::soreness),WorkoutViews.gap(ui,12));
        JSONArray cardio=overview().optJSONArray("cardio_personal_records");if(cardio!=null&&cardio.length()>0){LinearLayout r=WorkoutViews.card(ui);r.addView(ui.type("Run bests",15,20,700,0,ui.text));for(int i=0;i<cardio.length();i++){JSONObject p=cardio.optJSONObject(i);r.addView(WorkoutViews.pair(ui,WorkoutViews.kg(Math.round(p.optDouble("distance_m")/10)/100.0)+" km",WorkoutViews.clock(p.optLong("seconds"))+" · "+WorkoutViews.kg(p.optDouble("speed_kmh"))+" km/h",ui.text));}s.body.addView(r,WorkoutViews.gap(ui,12));}
        new WorkoutPhotos(this,s).fill();}
    private void measure(WorkoutViews.Sheet s,String kind,String unit,String hint){EditText field=ui.field(hint,"");field.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);new AlertDialog.Builder(a).setTitle(hint).setView(field).setPositiveButton("Save",(x,i)->{try{double v=WorkoutUnits.loadIn(a,Double.parseDouble(field.getText().toString().trim().replace(',','.')));if(v<=0)return;WorkoutStore.put(a,"measurement",WorkoutStore.id(),new JSONObject().put("measured_at",OffsetDateTime.now().withNano(0).toString()).put("kind",kind).put("value",v).put("unit",unit).put("source","Companion"));refreshThen(()->fillBody(s));}catch(Exception e){Toast.makeText(a,"Enter a number",Toast.LENGTH_SHORT).show();}}).setNegativeButton("Cancel",null).show();}
    private void refreshThen(Runnable after){render();new Thread(()->{String m=WorkoutStore.sync(a);a.runOnUiThread(()->{problem=m;render();after.run();});}).start();}
    private void soreness(){LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);TextView label=ui.detail("Soreness 3 of 10");SeekBar bar=new SeekBar(a);bar.setMax(10);bar.setProgress(3);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean f){label.setText("Soreness "+v+" of 10");}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});EditText where=ui.field("Where, for example legs","");EditText pain=ui.field("Any pain? Describe it","");box.addView(label);box.addView(bar,WorkoutViews.gap(ui,8));box.addView(where,WorkoutViews.gap(ui,8));box.addView(pain);new AlertDialog.Builder(a).setTitle("How do you feel?").setView(box).setPositiveButton("Save",(x,i)->{try{JSONObject r=new JSONObject().put("observed_at",OffsetDateTime.now().withNano(0).toString()).put("soreness",bar.getProgress()).put("pain",pain.getText().toString().trim());String m=where.getText().toString().trim();if(!m.isEmpty())r.put("muscles",new JSONArray().put(m));WorkoutStore.put(a,"recovery",WorkoutStore.id(),r);refresh();}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}

