        Switch imperial=new Switch(a);imperial.setText("Pounds and miles");imperial.setTag("workout_imperial");imperial.setChecked("imperial".equals(d.optString("units")));s.body.addView(imperial,WorkoutViews.gap(ui,14));LinearLayout row=ui.row();LinearLayout w=ui.column();w.addView(ui.type("Automatic coach briefs",15,20,600,0,ui.text));w.addView(ui.type("Uses your Codex subscription, never photos.",12.5f,17,400,0,ui.muted));row.addView(w,new LinearLayout.LayoutParams(0,-2,1));Switch auto=new Switch(a);auto.setTag("coach_auto_briefs");auto.setChecked(p==null||d.optBoolean("auto_coach_briefs",true));row.addView(auto);s.body.addView(row,WorkoutViews.gap(ui,16));
